package com.vitalminds.controller;
import com.vitalminds.model.*; import com.vitalminds.repository.*; import com.vitalminds.service.*; import org.springframework.http.*; import org.springframework.security.core.Authentication; import org.springframework.stereotype.Controller; import org.springframework.web.bind.annotation.*; import java.nio.charset.StandardCharsets; import java.time.*; import java.util.*;
@Controller public class V7Controller {
 private final UserService users; private final HydrationLogRepository hydration; private final MealLogRepository meals; private final WorkoutPlanRepository workouts; private final HealthAlertRepository alerts; private final HealthRecordRepository records; private final HealthSummaryService summary; private final HealthInsightsService insights;
 public V7Controller(UserService u,HydrationLogRepository h,MealLogRepository m,WorkoutPlanRepository w,HealthAlertRepository a,HealthRecordRepository r,HealthSummaryService s,HealthInsightsService i){users=u;hydration=h;meals=m;workouts=w;alerts=a;records=r;summary=s;insights=i;}
 private User user(Authentication a){return users.findByEmail(a.getName()).orElseThrow();}
 @PostMapping("/api/hydration") public String hydration(Authentication a,@RequestParam String date,@RequestParam Double liters,@RequestParam(required=false)Integer glasses){HydrationLog x=new HydrationLog();x.setUser(user(a));x.setDate(LocalDate.parse(date));x.setLiters(liters);x.setGlasses(glasses);hydration.save(x);return "redirect:/dashboard?v7Saved";}
 @PostMapping("/api/meals") public String meal(Authentication a,@RequestParam String date,@RequestParam String mealType,@RequestParam String food,@RequestParam(required=false)Integer calories){MealLog x=new MealLog();x.setUser(user(a));x.setDate(LocalDate.parse(date));x.setMealType(mealType);x.setFood(food);x.setCalories(calories);meals.save(x);return "redirect:/dashboard?v7Saved";}
 @PostMapping("/api/workouts") public String workout(Authentication a,@RequestParam String date,@RequestParam String type,@RequestParam Integer minutes,@RequestParam String intensity,@RequestParam(required=false)String notes){WorkoutPlan x=new WorkoutPlan();x.setUser(user(a));x.setDate(LocalDate.parse(date));x.setType(type);x.setMinutes(minutes);x.setIntensity(intensity);x.setNotes(notes);workouts.save(x);return "redirect:/dashboard?v7Saved";}
 @PostMapping("/api/alerts/{id}/read") public String read(Authentication a,@PathVariable Long id){User u=user(a);alerts.findById(id).filter(x->x.getUser().getId().equals(u.getId())).ifPresent(x->{x.setReadFlag(true);alerts.save(x);});return "redirect:/dashboard";}
 @PostMapping("/api/alerts/refresh") public String refresh(Authentication a){User u=user(a);var rs=records.findTop20ByUserIdOrderByUploadedAtDesc(u.getId());if(!rs.isEmpty())alerts.saveAll(insights.buildAlerts(u,rs.get(0)));return "redirect:/dashboard?alertsRefreshed";}
 @GetMapping("/api/health-summary.pdf") public ResponseEntity<byte[]> pdf(Authentication a)throws Exception{User u=user(a);var rs=records.findTop20ByUserIdOrderByUploadedAtDesc(u.getId());var acts=List.<ActivityLog>of();var sl=List.<SleepLog>of();int score=insights.score(u,rs.isEmpty()?null:rs.get(0),acts,sl);byte[] b=summary.create(u,rs.isEmpty()?null:rs.get(0),score,insights.recommendations(u,rs.isEmpty()?null:rs.get(0),acts,sl));return ResponseEntity.ok().header(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename=VitalMinds-V7-Health-Summary.pdf").contentType(MediaType.APPLICATION_PDF).body(b);}
 @GetMapping("/api/export-v7") public ResponseEntity<byte[]> csv(Authentication a){User u=user(a);var rs=records.findTop20ByUserIdOrderByUploadedAtDesc(u.getId());StringBuilder s=new StringBuilder("Date,File,Hemoglobin,Glucose,Cholesterol,Systolic,Diastolic,BMI,Summary\n");for(var r:rs)s.append(q(String.valueOf(r.getUploadedAt()))).append(',').append(q(r.getFileName())).append(',').append(v(r.getHemoglobin())).append(',').append(v(r.getGlucose())).append(',').append(v(r.getCholesterol())).append(',').append(v(r.getSystolic())).append(',').append(v(r.getDiastolic())).append(',').append(v(r.getBmi())).append(',').append(q(r.getSummary())).append('\n');return ResponseEntity.ok().header(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename=VitalMinds-V7-health-data.csv").contentType(MediaType.parseMediaType("text/csv")).body(s.toString().getBytes(StandardCharsets.UTF_8));}
 private String v(Object o){return o==null?"":o.toString();}private String q(String s){return "\""+(s==null?"":s.replace("\"","\"\""))+"\"";}
}
